import React, { ReactNode, useRef } from 'react';

import { Store, createStore } from '../../../core/store/store.js';
import { TimeseriesChartStateContext } from '../context/TimeseriesChartState.context.js';
import { TimeseriesChartState, initialState } from '../types/state.js';

export const StoreProvider = ({ children }: { children: ReactNode }) => {
  const storeRef = useRef<Store<TimeseriesChartState>>();

  storeRef.current = createStore({
    ...initialState,
    filteredSeriesIds: new Set(),
  });

  return (
    <TimeseriesChartStateContext.Provider value={storeRef.current}>
      {children}
    </TimeseriesChartStateContext.Provider>
  );
};

StoreProvider['displayName'] = 'StoreProvider';
